<script>document.addEventListener('DOMContentLoaded',()=>{const money=n=>new Intl.NumberFormat('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n||0),s=document.querySelector('#selling-price'),f=document.querySelector('#first-payment'),c=document.querySelector('#installment-count'),a=document.querySelector('#installment-amount'),out=document.querySelector('#finance-summary');let automatic=true;const draw=()=>{const selling=Number(s.value||0),first=Number(f.value||0),count=Math.max(1,Number(c.value||1)),balance=Math.max(0,selling-first),suggested=Math.round(balance/count*100)/100;if(automatic||!a.value)a.value=suggested.toFixed(2);const selected=Number(a.value||0),expected=selected*count,adjust=balance-selected*(count-1);out.innerHTML=`<div><strong>Selling</strong><br>LKR ${money(selling)}</div><div><strong>Financed balance</strong><br>LKR ${money(balance)}</div><div><strong>Suggested installment</strong><br>LKR ${money(suggested)}</div><div><strong>Final adjustment</strong><br>Final LKR ${money(adjust)} · Difference LKR ${money(expected-balance)}</div>`};[s,f,c].forEach(x=>x.addEventListener('input',draw));a.addEventListener('input',()=>{automatic=false;draw()});draw();const p=document.querySelector('#management-pin'),pc=document.querySelector('#management-pin-confirmation');document.querySelector('#toggle-management-pin').onclick=()=>{const show=p.type==='password';p.type=pc.type=show?'text':'password'};document.querySelector('#generate-management-pin').onclick=()=>{let v;do{v=String(crypto.getRandomValues(new Uint32Array(1))[0]%10000).padStart(4,'0')}while(['0000','1111','1234','4321'].includes(v));p.value=pc.value=v};document.querySelector('#copy-management-pin').onclick=()=>navigator.clipboard.writeText(p.value);document.querySelector('#device-form').addEventListener('submit',()=>{document.querySelectorAll('[data-submit]').forEach(b=>{b.disabled=true;b.textContent='Saving…'})})});</script></x-layouts.app>
